def lstat_inspect(path: str) -> dict:
    st = os.lstat(path)
    return {
        "path": path,
        "is_regular": stat.S_ISREG(st.st_mode),
        "is_symlink": stat.S_ISLNK(st.st_mode),
        "size": st.st_size,
        "mode_oct": oct(st.st_mode & 0o777),
    }


def read_nofollow(path: str) -> bytes:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(path, flags)
    try:
        with os.fdopen(fd, "rb") as f:
            return f.read()
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        raise


def sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def collect_keys(obj, acc: set) -> None:
    if isinstance(obj, dict):
        for k, v in obj.items():
            acc.add(k)
            collect_keys(v, acc)
    elif isinstance(obj, list):
        for item in obj:
            collect_keys(item, acc)


