def scan_forbidden_keys(obj) -> list[str]:
    keys: set[str] = set()
    collect_keys(obj, keys)
    hits = []
    for k in sorted(keys):
        if k in ALLOWED_OPAQUE_KEYS:
            continue
        if k in FORBIDDEN_EXACT_KEYS:
            hits.append(f"EXACT:{k}")
            continue
        kl = k.lower()
        for tok in FORBIDDEN_KEY_TOKENS:
            if tok in kl:
                hits.append(f"TOKEN:{tok}:{k}")
        if k == "content_class":
            hits.append(f"EXACT:{k}")
        # fragment scan, excluding allowed/required identifiers already skipped
        for frag in FORBIDDEN_NAME_FRAGMENTS:
            if frag in kl:
                hits.append(f"FRAG:{frag}:{k}")
        # 'current' except opaque currentness_epistemic_status (already skipped)
        # posting kinds are values, not keys. 'CURRENTNESS_TOKEN_LINE' is a value.
        if "currentness" in kl and k != "currentness_epistemic_status":
            hits.append(f"CURRENTNESS_KEY:{k}")
        if kl == "current" or kl.startswith("current_") or kl.endswith("_current"):
            hits.append(f"CURRENT_KEY:{k}")
        if "canonical" in kl and k != "creates_canonical_authority":
            hits.append(f"CANONICAL_KEY:{k}")
        if "truth" in kl and k != "creates_source_truth":
            hits.append(f"TRUTH_KEY:{k}")
        if "master" in kl:
            hits.append(f"MASTER_KEY:{k}")
        if kl in {"active", "final"}:
            hits.append(f"STATUS_KEY:{k}")
    # unique preserve order
    seen = set()
    out = []
    for h in hits:
        if h not in seen:
            seen.add(h)
            out.append(h)
    return out


