        },
    }

    pre_write_key_hits = scan_forbidden_keys(projection)
    if pre_write_key_hits:
        fail("FORBIDDEN_SEMANTIC_KEY_SCAN_PREWRITE:" + ",".join(pre_write_key_hits))
        emit_stop(pwd, porcelain_pre, porcelain_pre, write_performed, source_sha, ptf1_sha, None, None)
        return 2

    encoded = json.dumps(projection, ensure_ascii=False, indent=2, sort_keys=False) + "\n"
    encoded_bytes = encoded.encode("utf-8")

    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(OUTPUT, flags, 0o644)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(encoded_bytes)
            f.flush()
            os.fsync(f.fileno())
    except Exception:
        try:
            os.close(fd)
        except OSError:
            pass
        raise
    write_performed = True

    # PHASE 10
    source_bytes_post = read_nofollow(SOURCE)
    ptf1_bytes_post = read_nofollow(PTF1)
    source_sha_post = sha256_hex(source_bytes_post)
    ptf1_sha_post = sha256_hex(ptf1_bytes_post)
    if source_bytes_post != source_bytes:
        fail("SOURCE_MUTATED")
    if ptf1_bytes_post != ptf1_bytes:
        fail("PTF1_MUTATED")
    if source_sha_post != REQUIRED_SOURCE_SHA256:
        fail("SOURCE_SHA_POST_MISMATCH")
    if ptf1_sha_post != REQUIRED_PTF1_SHA256:
        fail("PTF1_SHA_POST_MISMATCH")

    out_st = lstat_inspect(OUTPUT)
    if not out_st["is_regular"] or out_st["is_symlink"]:
        fail("OUTPUT_NOT_REGULAR_OR_SYMLINK")
    output_bytes = read_nofollow(OUTPUT)
    output_sha = sha256_hex(output_bytes)
    if output_bytes != encoded_bytes:
        fail("OUTPUT_READBACK_MISMATCH")

    try:
        parsed = json.loads(output_bytes.decode("utf-8"))
    except Exception as exc:
        fail(f"OUTPUT_JSON_PARSE:{exc}")
        porcelain_post = git_porcelain()
        emit_stop(
            pwd,
            porcelain_pre,
            porcelain_post,
            write_performed,
            source_sha_post,
            ptf1_sha_post,
            out_st,
            output_sha,
        )
        return 2

    if parsed.get("target_model_id") != "PT_FORENSIC_LOSSLESS_STRUCTURAL_PROJECTION_SPEC_V1":
        fail("OUTPUT_TARGET_MODEL_ID")
    if parsed.get("target_role") != "LOSSLESS_REPRESENTATION_ONLY":
        fail("OUTPUT_TARGET_ROLE")
    if parsed.get("target_authority_status") != "NONE":
        fail("OUTPUT_TARGET_AUTHORITY_STATUS")
    if parsed.get("creates_source_truth") is not False:
        fail("OUTPUT_CREATES_SOURCE_TRUTH")
    if parsed.get("creates_canonical_authority") is not False:
        fail("OUTPUT_CREATES_CANONICAL_AUTHORITY")

    lsp = parsed["lossless_structural_projection"]
    recs = lsp["reconstruction_member_records"]
    nrecs = lsp["nested_projection_records"]
    precords = lsp["span_local_posting_records"]
    if len(recs) != REQUIRED_MEMBER_COUNT:
        fail("OUTPUT_MEMBER_COUNT")
    if len(nrecs) != REQUIRED_NESTED_VIEW_COUNT:
        fail("OUTPUT_NESTED_COUNT")
    if any(r.get("reconstruction_member") is not True for r in recs):
        fail("OUTPUT_MEMBER_RECON_FLAG")
    if any(v.get("reconstruction_member") is not False for v in nrecs):
        fail("OUTPUT_NESTED_RECON_FLAG")
    nested_true_out = sum(1 for v in nrecs if v.get("reconstruction_member") is True)
    kind_counts_out = Counter(p["kind"] for p in precords)
    for k, n in REQUIRED_POSTING_COUNTS.items():
        if kind_counts_out.get(k, 0) != n:
            fail(f"OUTPUT_POSTING_COUNT_{k}")

    unset_out = lsp["spec_constraint_layer"]["unset_owner_decisions"]
    if unset_out != UNSET_DECISIONS:
        fail("UNSET_DECISIONS_MUTATED")

    key_hits = scan_forbidden_keys(parsed)
    if key_hits:
        fail("FORBIDDEN_SEMANTIC_KEY_SCAN:" + ",".join(key_hits))

    # provenance vs source
    out_member_by_id = {m["source_block_id"]: m for m in recs}
    reconstructed_post = b"".join(
        source_bytes_post[m["source_byte_start"] : m["source_byte_end_exclusive"]]
        for m in sorted(recs, key=lambda x: x["original_order_index"])
    )
    if reconstructed_post != source_bytes_post:
        fail("OUTPUT_RECONSTRUCTION_BYTES_MISMATCH")
    if sha256_hex(reconstructed_post) != source_sha_post:
        fail("OUTPUT_RECONSTRUCTION_SHA_MISMATCH")
    if recs[0]["source_byte_start"] != 0:
        fail("OUTPUT_COVERAGE_START")
    if recs[-1]["source_byte_end_exclusive"] != REQUIRED_BYTE_LENGTH:
        fail("OUTPUT_COVERAGE_END")
    prev_end = 0
    for i, m in enumerate(recs):
        if m["source_byte_start"] != prev_end:
            fail(f"OUTPUT_GAP_OR_OVERLAP_{i}")
        sl = source_bytes_post[m["source_byte_start"] : m["source_byte_end_exclusive"]]
        if sha256_hex(sl) != m["source_sha256"]:
            fail(f"OUTPUT_MEMBER_HASH_{m['source_block_id']}")
        prev_end = m["source_byte_end_exclusive"]
        if m["original_order_index"] != i:
            fail(f"OUTPUT_ORDER_INDEX_{i}")
    if [m["source_block_id"] for m in recs] != lsp["reconstruction_manifest"]["ordered_member_ids"]:
        fail("OUTPUT_ORDERED_IDS_MANIFEST")
    if lsp["reconstruction_manifest"]["ordered_member_ids"] != ordered_ids:
        fail("OUTPUT_MANIFEST_IDS_DRIFT")

    for v in nrecs:
        parent = out_member_by_id.get(v["parent_source_block_id"])
        if parent is None:
            fail(f"OUTPUT_VIEW_PARENT_{v.get('view_id')}")
            continue
        if not (
            v["source_byte_start"] >= parent["source_byte_start"]
            and v["source_byte_end_exclusive"] <= parent["source_byte_end_exclusive"]
        ):
            fail(f"OUTPUT_VIEW_OUTSIDE_PARENT_{v.get('view_id')}")
        sl = source_bytes_post[v["source_byte_start"] : v["source_byte_end_exclusive"]]
        if sha256_hex(sl) != v["source_sha256"]:
            fail(f"OUTPUT_VIEW_HASH_{v.get('view_id')}")

    for p in precords:
        sl = source_bytes_post[p["source_byte_start"] : p["source_byte_end_exclusive"]]
        if bytes.fromhex(p["raw_bytes_hex"]) != sl:
            fail(f"OUTPUT_POSTING_HEX_{p.get('posting_id')}")

    # LF identity unchanged
    if source_bytes_post.count(b"\n") != fb["lf_count"]:
        fail("LF_COUNT_DRIFT")
    if b"\r" in source_bytes_post:
        fail("CR_POST")
    if source_bytes_post.startswith(b"\xef\xbb\xbf"):
        fail("BOM_POST")
    if b"\x00" in source_bytes_post:
        fail("NULL_POST")

    porcelain_post = git_porcelain()
    if porcelain_post.strip() != porcelain_pre.strip():
        fail("REPO_PORCELAIN_CHANGED")

    emit_report(
        pwd=pwd,
        porcelain_pre=porcelain_pre,
        porcelain_post=porcelain_post,
        write_performed=write_performed,
        source_sha_post=source_sha_post,
        ptf1_sha_post=ptf1_sha_post,
        out_st=out_st,
        output_sha=output_sha,
        recs=recs,
        nrecs=nrecs,
        kind_counts_out=kind_counts_out,
        nested_true_out=nested_true_out,
        key_hits=key_hits,
        reconstructed_ok=(reconstructed_post == source_bytes_post),
        reconstructed_sha_ok=(sha256_hex(reconstructed_post) == source_sha_post),
        source_mutated=(source_bytes_post != source_bytes),
        ptf1_mutated=(ptf1_bytes_post != ptf1_bytes),
        unset_out=unset_out,
    )
    return 0 if not failures else 2


def emit_stop(pwd, porcelain_pre, porcelain_post, write_performed, source_sha_post, ptf1_sha_post, out_st, output_sha):
    emit_report(
        pwd=pwd,
        porcelain_pre=porcelain_pre,
        porcelain_post=porcelain_post,
        write_performed=write_performed,
        source_sha_post=source_sha_post,
        ptf1_sha_post=ptf1_sha_post,
        out_st=out_st,
        output_sha=output_sha,
        recs=[],
        nrecs=[],
        kind_counts_out=Counter(),
        nested_true_out=None,
        key_hits=[],
        reconstructed_ok=False,
        reconstructed_sha_ok=False,
        source_mutated=False,
        ptf1_mutated=False,
        unset_out=UNSET_DECISIONS,
    )


def emit_report(
    *,
    pwd,
    porcelain_pre,
    porcelain_post,
    write_performed,
    source_sha_post,
    ptf1_sha_post,
    out_st,
    output_sha,
    recs,
    nrecs,
    kind_counts_out,
    nested_true_out,
    key_hits,
    reconstructed_ok,
    reconstructed_sha_ok,
    source_mutated,
    ptf1_mutated,
    unset_out,
):
    ok = not failures
    porcelain_post_disp = "EMPTY" if (porcelain_post or "") == "" else repr(porcelain_post)
    print("BEGIN_FORENSIC_RESULT_REPORT")
    print(f"PWD={pwd}")
    print(f"GIT_STATUS_PORCELAIN_PRE={'EMPTY' if porcelain_pre == '' else repr(porcelain_pre)}")
    print(f"WRITE_PERFORMED={str(write_performed).lower()}")
    print(f"BASELINE_VALIDATION={'PASS_LOSSLESS_STRUCTURAL_PROJECTION_ONLY' if ok else 'HARD_STOP'}")
    print(f"SOURCE_PREIMAGE_MATCH={str((source_sha_post == REQUIRED_SOURCE_SHA256) and not source_mutated).lower()}")
    print(f"PTF1_BINDING_MATCH={str((ptf1_sha_post == REQUIRED_PTF1_SHA256) and not ptf1_mutated).lower()}")
    print(f"RECONSTRUCTION_MATCH={str(reconstructed_ok and reconstructed_sha_ok).lower()}")
    print(f"OUTPUT_PATH={OUTPUT if write_performed else 'NONE'}")
    print(f"OUTPUT_REGULAR={str(bool(out_st and out_st.get('is_regular'))).lower()}")
    print(f"OUTPUT_SYMLINK={str(bool(out_st and out_st.get('is_symlink'))).lower()}")
    print(f"OUTPUT_SIZE={out_st['size'] if out_st else 'NONE'}")
    print(f"OUTPUT_SHA256={output_sha if output_sha else 'NONE'}")
    print(f"SOURCE_SHA256_POST={source_sha_post if source_sha_post else 'NONE'}")
    print(f"PTF1_SHA256_POST={ptf1_sha_post if ptf1_sha_post else 'NONE'}")
    print(f"SOURCE_MUTATED={str(source_mutated).lower()}")
    print(f"PTF1_MUTATED={str(ptf1_mutated).lower()}")
    porcelain_changed = (porcelain_post or "") != (porcelain_pre or "")
    print(f"REPO_MUTATED={str(porcelain_changed).lower()}")
    print("FETCH_PERFORMED=false")
    print("NETWORK_USED=false")
    print(f"TRANSFORMATION_PERFORMED={str(write_performed).lower()}")
    print(f"TRANSFORMATION_OUTPUT_VALID={str(ok and write_performed).lower()}")
    print("CANONICALIZATION_PERFORMED=false")
    print("CLASS_D_ADMISSION_PERFORMED=false")
    print("AUTHORITY_PROMOTION_PERFORMED=false")
    print("TARGET_AUTHORITY=NONE")
    print(f"RECONSTRUCTION_MEMBER_COUNT={len(recs) if recs else (0 if write_performed else 'NA')}")
    print(f"NESTED_PROJECTION_COUNT={len(nrecs) if nrecs else (0 if write_performed else 'NA')}")
    print(f"NESTED_RECONSTRUCTION_MEMBER_TRUE={nested_true_out if nested_true_out is not None else 'NA'}")
    print(f"CURRENT_ORIGIN_MAIN_SHA_POSTING_COUNT={kind_counts_out.get('CURRENT_ORIGIN_MAIN_SHA', 'NA')}")
    print(f"TARGET_AUTHORITY_NONE_EXACT_COUNT={kind_counts_out.get('TARGET_AUTHORITY_NONE_EXACT', 'NA')}")
    print(f"TARGET_AUTHORITY_NONE_INLINE_COUNT={kind_counts_out.get('TARGET_AUTHORITY_NONE_INLINE', 'NA')}")
    print(f"CURRENTNESS_TOKEN_LINE_COUNT={kind_counts_out.get('CURRENTNESS_TOKEN_LINE', 'NA')}")
    print(f"UNSET_DECISIONS={';'.join(unset_out)}")
    print(f"FORBIDDEN_SEMANTIC_KEY_SCAN={'PASS' if not key_hits else 'FAIL:' + ','.join(key_hits)}")
    print(f"ROUND_TRIP_BYTE_IDENTITY={str(reconstructed_ok).lower()}")
    print(f"ROUND_TRIP_SHA_IDENTITY={str(reconstructed_sha_ok).lower()}")
    print(f"GIT_STATUS_PORCELAIN_POST={porcelain_post_disp}")
    print(f"HARD_STOP_REASONS={'NONE' if ok else ';'.join(failures)}")
    print(
        "TRANSFORMATION_STATUS="
        + ("PASS_LOSSLESS_STRUCTURAL_PROJECTION_ONLY" if ok else "HARD_STOP")
    )
    print("STOP=true")
    print("END_FORENSIC_RESULT_REPORT")


if __name__ == "__main__":
    os.chdir(REPO)
    sys.exit(main())
